    "code": "import time\nrng = np.random.default_rng(0)\nX, caps, labels = make(20000, rng)\nm = TinyCLIP(Vocab(caps + [\"a %s %s %s\" % (s, c, sh) for sh, c, s in classes()]), prep=prep_chroma, d_in=768)\ntrain(m, X, caps, epochs=15, kind='sigmoid')        # chroma input, sigmoid loss (about half a minute)\nA, _, la = make(4000, rng); Bu, _, lb = make(1000, rng, unseen=True)\nframes, flabels = np.concatenate([A, Bu]), la + lb   # the archive: 5,000 frames, 1,000 from unseen combinations\ndef matches(query, l):\n    w = query.split()\n    return all(not [v for v in g if v in w] or l[k] in w for k, g in enumerate((SHAPES, list(COLORS), SIZES)))\n",
