    "code": "def proposals(img):\n    f = img.astype(np.int16)\n    mask = ((f.max(2) - f.min(2)) > 90).astype(np.uint8)\n    n, _, stats, _ = cv2.connectedComponentsWithStats(mask)\n    boxes = [(x, y, x + w, y + h) for x, y, w, h, a in stats[1:] if a >= 20]\n    pad = cv2.copyMakeBorder(img, 16, 16, 16, 16, cv2.BORDER_REFLECT)\n    return boxes, np.array([pad[(y0 + y1) // 2:(y0 + y1) // 2 + 32, (x0 + x1) // 2:(x0 + x1) // 2 + 32] for x0, y0, x1, y1 in boxes])\n\ncrops, crop_labels = [], []                       # the crops of chapter 7 that hit a real object, with its label\nfor k in range(300):\n    img, objs = make_scene(rng)\n    boxes, cr = proposals(img)\n    for b, c in zip(boxes, cr):\n        j = max(range(len(objs)), key=lambda j: iou(b, objs[j][1]))\n        if iou(b, objs[j][1]) > 0.5:\n            crops.append(c); crop_labels.append(objs[j][0])\ncrops = np.array(crops)\n",
